// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Tracking {
    enum ShipmentStatus {PENDING, IN_TRANSITION, DELIVERED, CANCELLED}

    struct Shipment {
        address sender;
        address receiver;
        uint256 pickupTime;
        uint256 deliveryTime;
        uint256 distance;
        uint256 price;
        ShipmentStatus status;
        bool isPaid;
    }
    mapping(address => Shipment[]) public shipments;

    uint public shipmentCount;

    struct TypeShipment {
        address sender;
        address receiver;
        uint256 pickupTime;
        uint256 deliveryTime;
        uint256 distance;
        uint256 price;
        ShipmentStatus status;
        bool isPaid;
    }

    TypeShipment[] public typeShipments;

    event ShipmentCreated(address indexed sender, address indexed receiver, uint256 pickupTime, uint256 distance, uint256 price);

    event ShipmentInTransition(address indexed sender, address indexed receiver, uint256 pickupTime);

    event ShipmentDelivered(address indexed sender, address indexed receiver, uint256 deliveryTime);

    event ShipmentCancelled(address indexed sender, address indexed receiver, uint256 pickupTime);

    event ShipmentPaid(address indexed sender, address indexed receiver, uint256 amount);

    constructor() {
        shipmentCount = 0;
    }

    function createShipment(address _receiver, uint256 _pickupTime, uint256 _distance, uint256 _price) public payable {
        require(msg.value >= _price, "Insufficient payment for shipment");
        Shipment memory newShipment = Shipment(msg.sender, _receiver, _pickupTime, 0, _distance, _price, ShipmentStatus.PENDING, false);
        shipments[msg.sender].push(newShipment);
        shipmentCount++;
        typeShipments.push(TypeShipment(msg.sender, _receiver, _pickupTime, 0, _distance, _price, ShipmentStatus.PENDING, false));
        emit ShipmentCreated(msg.sender, _receiver, _pickupTime, _distance, _price);
    }

    function StartShipment(address _sender, address _receiver, uint256 _index) public {
        Shipment storage shipment = shipments[_sender][_index];
        TypeShipment storage typeShipment = typeShipments[_index];
        require(shipment.receiver == _receiver,"Invalid receiver");
        require(shipment.status == ShipmentStatus.PENDING, "Shipment is not pending");
        shipment.status = ShipmentStatus.IN_TRANSITION;
        typeShipment.status = ShipmentStatus.IN_TRANSITION;
        emit ShipmentInTransition(_sender, shipment.receiver, shipment.pickupTime);
    }

    function cancelShipment(address _sender, address _receiver, uint256 _index) public {
        Shipment storage shipment = shipments[_sender][_index];
        TypeShipment storage typeShipment = typeShipments[_index];
        require(shipment.receiver == _receiver, "Invalid receiver");
        require(shipment.status == ShipmentStatus.PENDING, "Shipment is not pending");
        require(!shipment.isPaid, "Shipment is already paid");
        shipment.status = ShipmentStatus.CANCELLED;
        typeShipment.status = ShipmentStatus.CANCELLED;
        uint256 amount = shipment.price;
        (bool success, ) = payable(shipment.sender).call{value: amount}("");
        require(success, "Refund failed");
        emit ShipmentCancelled(_sender, _receiver, shipment.pickupTime);
    }

    function completeShipment(address _sender, address _receiver, uint256 _index) public {
        Shipment storage shipment = shipments[_sender][_index];
        TypeShipment storage typeShipment = typeShipments[_index];
        require(shipment.receiver == _receiver,"Invalid receiver");
        require(shipment.status == ShipmentStatus.IN_TRANSITION, "Shipment is not in transition");
        require(!shipment.isPaid, "Shipment is already paid");
        shipment.status = ShipmentStatus.DELIVERED;
        shipment.deliveryTime = block.timestamp;
        typeShipment.status = ShipmentStatus.DELIVERED;
        typeShipment.deliveryTime = block.timestamp;
        uint256 amount = shipment.price;
        (bool success, ) = payable(shipment.sender).call{value: amount}("");
        require(success, "Payment failed");
        shipment.isPaid = true;
        typeShipment.isPaid = true;
        emit ShipmentDelivered(_sender, _receiver, shipment.deliveryTime);
        emit ShipmentPaid(_sender, _receiver, amount);
    }

    function getShipment(address _sender, uint256 _index) public view returns (address, address, uint256, uint256, uint256, uint256, ShipmentStatus, bool) {
        Shipment storage shipment = shipments[_sender][_index];
        return (shipment.sender, shipment.receiver, shipment.pickupTime, shipment.deliveryTime, shipment.distance, shipment.price, shipment.status, shipment.isPaid);
    }

    function getShipmentCount(address _sender) public view returns (uint256) {
        return shipments[_sender].length;
    }

    function getAllTransactions() public view returns (TypeShipment[] memory) {
        return typeShipments;
    }
}
